#include <bits/stdc++.h>
using namespace std;
using ll = long long;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, L, R, K;
    string s;
    cin >> n >> L >> R >> K >> s;
    struct S {
        array<int, 26> to{};
        int len = 0, link = -1;
        ll cnt = 0;
    };
    vector<S> a(2 * n + 1);
    int sz = 1, last = 0;
    for (char c : s) {
        int x = c - 'a', cur = sz++;
        a[cur].len = a[last].len + 1;
        a[cur].cnt = 1;
        int p = last;
        while (p != -1 && !a[p].to[x]) {
            a[p].to[x] = cur;
            p = a[p].link;
        }
        if (p == -1)
            a[cur].link = 0;
        else {
            int q = a[p].to[x];
            if (a[p].len + 1 == a[q].len)
                a[cur].link = q;
            else {
                int z = sz++;
                a[z] = a[q];
                a[z].len = a[p].len + 1;
                a[z].cnt = 0;
                while (p != -1 && a[p].to[x] == q) {
                    a[p].to[x] = z;
                    p = a[p].link;
                }
                a[q].link = a[cur].link = z;
            }
        }
        last = cur;
    }
    vector<vector<int>> b(n + 1);
    for (int v = 1; v < sz; v++)
        b[a[v].len].push_back(v);
    ll ans = 0;
    for (int l = n; l; l--)
        for (int v : b[l]) {
            if (a[v].cnt == K)
                ans += max(0, min(R, a[v].len) - max(L, a[a[v].link].len + 1) + 1);
            a[a[v].link].cnt += a[v].cnt;
        }
    cout << ans << '\n';
}

