    auto ok = [&](ll t) {
        ll z = 0;
        for (auto [p, k, r] : a) {
            ll c = p * k + r;
            z += t / c * k + min(k, t % c / p);
            if (z >= X)
                return true;
        }
        return false;
    };
    ll l = 0, r = 1;
    while (!ok(r))
        r *= 2;
    while (l < r) {
        ll m = (l + r) / 2;
        if (ok(m))
            r = m;
        else
            l = m + 1;
    }
    cout << l << '\n';
}

