import sys, bisect

it = iter(map(int, sys.stdin.buffer.read().split()))
q = next(it)
ops = [(next(it), next(it)) for _ in range(q)]
xs = sorted({x for op, x in ops if op != 3})
m = len(xs)
pos = {x: i for i, x in enumerate(xs)}
left = [0] * m
right = [0] * m
for i in range(m):
    left[i] = left[i - 1] if i and xs[i] == xs[i - 1] + 1 else i
for i in range(m - 1, -1, -1):
    right[i] = right[i + 1] if i + 1 < m and xs[i + 1] == xs[i] + 1 else i
size = 1
while size < m:
    size *= 2
tree = [0] * (2 * size)
on = [False] * m
bit = [0] * (q + 1)
total = 0


def change(k, sign):
    if not k:
        return
    v = k * sign
    while k <= q:
        bit[k] += v
        k += k & -k


def pref(k):
    s = 0
    while k:
        s += bit[k]
        k -= k & -k
    return s


def zero(l, r, rev=False):
    if l > r:
        return -1

    def find(v, a, b):
        if b < l or r < a or tree[v] == b - a + 1:
            return -1
        if a == b:
            return a
        mid = (a + b) // 2
        first, second = (
            ((v * 2 + 1, mid + 1, b), (v * 2, a, mid))
            if rev
            else ((v * 2, a, mid), (v * 2 + 1, mid + 1, b))
        )
        z = find(*first)
        return z if z != -1 else find(*second)

    return find(1, 0, size - 1)


out = []
for op, x in ops:
    if op == 3:
        out.append(str(total - pref(x - 1)))
        continue
    i = pos[x]
    if on[i] == (op == 1):
        continue
    l = zero(left[i], i - 1, True)
    r = zero(i + 1, right[i])
    a = i - (l if l != -1 else left[i] - 1) - 1
    b = (r if r != -1 else right[i] + 1) - i - 1
    if op == 1:
        change(a, -1)
        change(b, -1)
        change(a + b + 1, 1)
        total += 1
    else:
        change(a + b + 1, -1)
        change(a, 1)
        change(b, 1)
        total -= 1
    on[i] = op == 1
    v = size + i
    tree[v] = int(on[i])
    v //= 2
    while v:
        tree[v] = tree[2 * v] + tree[2 * v + 1]
        v //= 2
print("\n".join(out))

