using ll = long long;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> q;
    vector<pair<int, int>> ops(q);
    vector<int> x;
    for (auto &[o, v] : ops) {
        cin >> o >> v;
        if (o != 3)
            x.push_back(v);
    }
    sort(x.begin(), x.end());
    x.erase(unique(x.begin(), x.end()), x.end());
    int m = x.size();
    vector<int> L(m), R(m), bit(q + 1), on(m);
    for (int i = 0; i < m; i++)
        L[i] = (i && x[i] == x[i - 1] + 1) ? L[i - 1] : i;
    for (int i = m - 1; i >= 0; i--)
        R[i] = (i + 1 < m && x[i + 1] == x[i] + 1) ? R[i + 1] : i;
    set<int> off;
    for (int i = 0; i < m; i++)
        off.insert(i);
    auto change = [&](int k, int s) {
        int v = k * s;
        for (; k > 0 && k <= q; k += k & -k)
            bit[k] += v;
    };
    int total = 0;
    for (auto [o, v] : ops) {
        if (o == 3) {
            int z = 0;
            for (int k = v - 1; k; k -= k & -k)
                z += bit[k];
            cout << total - z << '\n';
            continue;
        }
        int i = lower_bound(x.begin(), x.end(), v) - x.begin();
        if (on[i] == (o == 1))
            continue;
        auto it = off.lower_bound(i + 1);
        int r = it == off.end() ? R[i] + 1 : min(R[i] + 1, *it);
        it = off.lower_bound(i);
        int l = L[i] - 1;
        if (it != off.begin())
            l = max(l, *prev(it));
        int a = i - l - 1, b = r - i - 1;
        if (o == 1) {
            change(a, -1);
            change(b, -1);
            change(a + b + 1, 1);
            total++;
            off.erase(i);
        } else {
            change(a + b + 1, -1);
            change(a, 1);
            change(b, 1);
            total--;
            off.insert(i);
        }
        on[i] = (o == 1);
    }
}

