    while l < r:
        if t[l] != t[r]:
            return False
        l += 1
        r -= 1
    return True


for start in range(n):
    t = s[start:] + s[:start]
    l = 0
    r = n - 1
    while l < r and t[l] == t[r]:
        l += 1
        r -= 1
    ways = 0
    if l >= r:
        a = (n - 1) // 2
        b = n // 2
        while a > 0 and t[a - 1] == t[a]:
            a -= 1
        while b + 1 < n and t[b + 1] == t[b]:
            b += 1
        ways = b - a + 1
    else:
        if pal(t, l + 1, r):
            a = l
            while a > 0 and t[a - 1] == t[l]:
                a -= 1
            ways += l - a + 1
        if pal(t, l, r - 1):
            b = r
            while b + 1 < n and t[b + 1] == t[r]:
                b += 1
            ways += b - r + 1
    rot += ways > 0
    total += ways
