#include <bits/stdc++.h>
using namespace std;
using ll = long long;
bool pal(const string &t, int l, int r) {
    while (l < r)
        if (t[l++] != t[r--])
            return false;
    return true;
}
int main() {
    int n;
    string s;
    cin >> n >> s;
    ll total = 0;
    int rot = 0;
    for (int st = 0; st < n; st++) {
        string t = s.substr(st) + s.substr(0, st);
        int l = 0, r = n - 1;
        while (l < r && t[l] == t[r])
            l++, r--;
        int ways = 0;
        if (l >= r) {
            int a = (n - 1) / 2, b = n / 2;
            while (a && t[a - 1] == t[a])
                a--;
            while (b + 1 < n && t[b + 1] == t[b])
                b++;
            ways = b - a + 1;
        } else {
            if (pal(t, l + 1, r)) {
                int a = l;
                while (a && t[a - 1] == t[l])
                    a--;
                ways += l - a + 1;
            }
            if (pal(t, l, r - 1)) {
                int b = r;
                while (b + 1 < n && t[b + 1] == t[r])
                    b++;
                ways += b - r + 1;
            }
        }
        rot += ways > 0;
        total += ways;
    }
    cout << rot << ' ' << total << '\n';
}

