                    z = s[0] - s[a] - s[b];
                if (z > best)
                    best = z, ways = 1;
                else if (z == best)
                    ways++;
            }
    if (!ways)
        cout << "IMPOSSIBLE\n";
    else
        cout << best << ' ' << ways << '\n';
}

