using ll = long long;
int H, W;
vector<int> r;
vector<vector<ll>> w;
map<tuple<int, int, vector<int>>, pair<ll, ll>> memo;
pair<ll, ll> dp(int i, int prev, vector<int> rem) {
    if (i == H) {
        for (int x : rem)
            if (x)
                return {0, 0};
        return {1, 0};
    }
    auto key = make_tuple(i, prev, rem);
    if (memo.count(key))
        return memo[key];
    ll count = 0, total = 0;
    for (int m = 0; m < (1 << W); m++)
        if (__builtin_popcount((unsigned)m) == r[i]) {
            int z = m & prev;
            if (z & (z >> 1))
                continue;
            auto nr = rem;
            ll v = 0;
            bool ok = true;
            for (int j = 0; j < W; j++) {
                int b = m >> (W - 1 - j) & 1;
                nr[j] -= b;
                v += w[i][j] * b;
                if (nr[j] < 0 || nr[j] > H - i - 1)
                    ok = false;
            }
            if (ok) {
                auto [c, s] = dp(i + 1, m, nr);
                count += c;
                total += s + c * v;
            }
        }
    return memo[key] = {count, total};
}
