using ll = long long;
using I = __int128_t;
ll eg(ll a, ll b, ll &x, ll &y) {
    if (!b) {
        x = 1;
        y = 0;
        return a;
    }
    ll u, v, g = eg(b, a % b, u, v);
    x = v;
    y = u - a / b * v;
    return g;
}
int main() {
    int n, b;
    ll L, R;
    cin >> n >> b >> L >> R;
    I a = 0, M = 1;
    bool ok = true;
    while (n--) {
        ll m, r;
        cin >> m >> r;
        r = (r % m + m) % m;
        ll g = gcd((ll)(M % m), m);
        if ((r - a) % g) {
            ok = false;
            continue;
        }
        ll v = m / g;
        I t = 0;
        if (v != 1) {
            ll x, y;
            eg((ll)(M / g % v), v, x, y);
            t = ((r - a) / g * x) % v;
            if (t < 0)
                t += v;
        }
        a += M * t;
        M *= v;
        a %= M;
    }
    vector<pair<ll, ll>> blocks;
    while (b--) {
        ll s, e;
        cin >> s >> e;
        s = max(s, L);
        e = min(e, R);
        if (s <= e)
            blocks.push_back({s, e});
    }
    sort(blocks.begin(), blocks.end());
    vector<pair<ll, ll>> allowed;
    ll cur = L;
    for (auto [s, e] : blocks) {
        if (cur < s)
            allowed.push_back({cur, s - 1});
        cur = max(cur, e + 1);
    }
    if (cur <= R)
        allowed.push_back({cur, R});
    ll count = 0, best = -1;
    if (ok)
        for (auto [l, r] : allowed) {
            I first = a;
            if (first < l)
                first += (I(l) - first + M - 1) / M * M;
            if (first <= r) {
                if (best < 0)
                    best = (ll)first;
                count += (ll)((r - first) / M + 1);
            }
        }
    cout << count << ' ' << best << '\n';
}

