            if (!types[0] || !types[1])
                return;
            for (int x : skill)
                if (x < 2)
                    return;
            if (score > best) {
                best = score;
                ways = 1;
                team = chosen;
            } else if (score == best) {
                ways++;
                team = min(team, chosen);
            }
            return;
        }
        int need = K - chosen.size();
        for (int i = st; i <= n - need; i++) {
            ll extra = v[i];
