@lru_cache(None)
def dp(pos, k, prev):
    if pos == n:
        return (0, 1, ()) if k == 0 else None
    if k == 0:
        return None
    best = None
    for i, (s, c, v) in enumerate(a, 1):
        if c == prev or not S.startswith(s, pos):
            continue
        tail = dp(pos + len(s), k - 1, c)
        if tail is None:
            continue
        score = v + tail[0]
        seq = (i,) + tail[2]
        if best is None or score > best[0]:
            best = (score, tail[1], seq)
        elif score == best[0]:
            best = (score, (best[1] + tail[1]) % 101, min(best[2], seq))
    return best


