#include <bits/stdc++.h>
using namespace std;
using ll = long long;
struct R {
    bool ok = false;
    ll score = 0;
    int count = 0;
    vector<int> seq;
};
int n, m, K;
string S;
vector<string> word;
vector<int> cat;
vector<ll> val;
R memo[61][61][3];
bool seen[61][61][3];
R dp(int p, int k, int prev) {
    if (p == n) {
        R r;
        if (k == 0)
            r.ok = true, r.count = 1;
        return r;
    }
    if (k == 0)
        return {};
    if (seen[p][k][prev])
        return memo[p][k][prev];
    seen[p][k][prev] = true;
    R best;
    for (int i = 0; i < m; i++)
        if (cat[i] != prev && S.compare(p, word[i].size(), word[i]) == 0) {
            R r = dp(p + word[i].size(), k - 1, cat[i]);
            if (!r.ok)
                continue;
            r.score += val[i];
            r.seq.insert(r.seq.begin(), i + 1);
            if (!best.ok || r.score > best.score)
                best = r;
            else if (r.score == best.score) {
                best.count = (best.count + r.count) % 101;
                best.seq = min(best.seq, r.seq);
            }
        }
    return memo[p][k][prev] = best;
}
int main() {
    cin >> n >> m >> K >> S;
    word.resize(m);
    cat.resize(m);
    val.resize(m);
    for (int i = 0; i < m; i++)
        cin >> word[i] >> cat[i] >> val[i];
    auto r = dp(0, K, 2);
    if (!r.ok)
        cout << "IMPOSSIBLE\n";
    else {
        cout << r.score << ' ' << r.count << '\n';
        for (int i = 0; i < K; i++)
            cout << (i ? " " : "") << r.seq[i];
        cout << '\n';
    }
}

