#include <bits/stdc++.h>
using namespace std;
using ll = long long;
pair<ll, ll> norm(ll a, ll b) {
    if (b < 0)
        a = -a, b = -b;
    ll g = gcd(abs(a), b);
    return {a / g, b / g};
}
int main() {
    int n;
    ll T;
    cin >> n >> T;
    vector<pair<ll, ll>> a(n);
    for (auto &[x, v] : a)
        cin >> x >> v;
    map<array<ll, 4>, set<int>> events;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < i; j++) {
            auto [x, v] = a[i];
            auto [y, w] = a[j];
            if (v == w)
                continue;
            auto [tn, td] = norm(y - x, v - w);
            if (tn <= 0 || (__int128)tn > (__int128)T * td)
                continue;
            auto [pn, pd] = norm(x * td + v * tn, td);
            auto &ids = events[{tn, td, pn, pd}];
            ids.insert(i);
            ids.insert(j);
        }
    if (events.empty()) {
        cout << "0 0\n-\n";
        return 0;
    }
    auto less = [](auto a, auto b) {
        __int128 x = (__int128)a[0] * b[1], y = (__int128)b[0] * a[1];
        if (x != y)
            return x < y;
        return (__int128)a[2] * b[3] < (__int128)b[2] * a[3];
    };
    auto best = events.begin()->first;
    int mx = 0;
    for (auto &[key, ids] : events) {
        mx = max(mx, (int)ids.size());
        if (less(key, best))
            best = key;
    }
    cout << events.size() << ' ' << mx << '\n';
    for (int i = 0; i < 4; i++)
        cout << (i ? " " : "") << best[i];
    cout << '\n';
}
